package org.apache.parquet.filter2;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class IncrementallyUpdatedFilterPredicateGeneratorRunTests {

  @TempDir
  Path temporaryDirectory;

  @Test
  void runWritesTheCompleteBuilderSource() throws IOException {
    Path output = temporaryDirectory.resolve("IncrementallyUpdatedFilterPredicateBuilder.java");

    new IncrementallyUpdatedFilterPredicateGenerator(output.toFile()).run();
    String source = Files.readString(output);

    assertTrue(source.startsWith("package org.apache.parquet.filter2.recordlevel;"));
    assertTrue(source.contains("public class IncrementallyUpdatedFilterPredicateBuilder extends IncrementallyUpdatedFilterPredicateBuilderBase {\n"));
    assertTrue(source.contains("public IncrementallyUpdatedFilterPredicateBuilder(List<PrimitiveColumnIO> leaves)"));
    assertTrue(source.endsWith("}\n"));

    // Every predicate family and every primitive representation supported by the
    // generator must have a dispatch branch in the emitted builder.
    for (String operator : new String[] {"Eq", "NotEq", "In", "NotIn", "Lt", "LtEq", "Gt", "GtEq"}) {
      assertTrue(source.contains("visit(" + operator + "<T> pred)"), operator);
    }
    for (String type : new String[] {"Integer", "Long", "Boolean", "Float", "Double", "Binary"}) {
      assertTrue(source.contains("clazz.equals(" + type + ".class)"), type);
    }
    assertTrue(source.contains("visit(Contains<T> pred)"));
    assertTrue(source.contains("visit(UserDefined<T, U> pred)"));
    assertTrue(source.contains("visit(LogicalNotUserDefined<T, U> notPred)"));
    assertTrue(source.contains("addValueInspector(columnPath, valueInspector)"));
  }

  @Test
  void logicalNotUserDefinedPredicatesAreInvertedInGeneratedCode() throws IOException {
    Path output = temporaryDirectory.resolve("IncrementallyUpdatedFilterPredicateBuilder.java");

    new IncrementallyUpdatedFilterPredicateGenerator(output.toFile()).run();
    String source = Files.readString(output);

    int ordinaryStart = source.indexOf("visit(UserDefined<T, U> pred)");
    int negatedStart = source.indexOf("visit(LogicalNotUserDefined<T, U> notPred)");
    assertTrue(ordinaryStart >= 0);
    assertTrue(negatedStart > ordinaryStart);

    String ordinary = source.substring(ordinaryStart, negatedStart);
    String negated = source.substring(negatedStart);

    // Logical negation changes both null and non-null predicate outcomes, while
    // the ordinary UserDefined visitor preserves the U predicate's result.
    assertTrue(ordinary.contains("setResult(udp.acceptsNullValue())"));
    assertTrue(ordinary.contains("setResult(udp.keep((T) (Object) value))"));
    assertTrue(negated.contains("setResult(!udp.acceptsNullValue())"));
    assertTrue(negated.contains("setResult(!udp.keep((T) (Object) value))"));
    assertFalse(negated.contains("setResult(udp.acceptsNullValue())"));
    assertFalse(negated.contains("setResult(udp.keep((T) (Object) value))"));

    assertEquals("}\n", source.substring(source.length() - 2));
  }
}

